  "internal_publicapi.Page": {
    "type": "object",
    "properties": {
      "createdAt": {
        "type": "string"
      },
      "group": {
        "description": "Group is the higher-level grouping derived from Type (main|store|blog|…).\nDerived, never settable — sending it changes nothing.",
        "type": "string"
      },
      "id": {
        "type": "string"
      },
      "isDefaultTemplate": {
        "description": "IsDefaultTemplate marks the page that renders its Type when an entity has\nno explicit link. At most one per (site, type).",
        "type": "boolean"
      },
      "isHomepage": {
        "type": "boolean"
      },
      "name": {
        "type": "string"
      },
      "path": {
        "type": "string"
      },
      "publishedAt": {
        "description": "PublishedAt is null until the page has a live published row. It is the one\nhonest way to answer \"is this live?\", which `status` alone does not.",
        "type": "string"
      },
      "settings": {
        "description": "Settings is the page's own SEO/settings document, passed through verbatim.\n\nIts INNER keys are explicitly NOT part of the frozen contract — this field\npromises only that whatever you store here comes back unchanged. That is a\ndeliberate seam rather than an oversight: the alternative was to omit it,\nwhich would leave a partner unable to set so much as a meta description,\nand pinning its shape would freeze a document the editor still evolves.\nRead it, change the keys you know, send the whole thing back.",
        "type": "array",
        "items": {
          "type": "integer"
        }
      },
      "slug": {
        "description": "Slug is EMPTY for the homepage, which is served at \"/\". Path carries the\nresolved URL either way, so a client that only wants to link to a page\nshould read Path and never rebuild it from Slug.",
        "type": "string"
      },
      "sortOrder": {
        "type": "integer"
      },
      "status": {
        "type": "string"
      },
      "type": {
        "description": "Type is the content kind (page|product|category|blog|post|error|…). The\nentity types are TEMPLATES: one page renders every product, so creating a\n\"product\" page does not create a product.",
        "type": "string"
      },
      "updatedAt": {
        "type": "string"
      }
    }
  },
