  "internal_publicapi.WebhookInput": {
    "type": "object",
    "properties": {
      "description": {
        "type": "string"
      },
      "events": {
        "description": "Events must name at least one type from webhooks.EventTypes(); an empty\nor unknown list is refused before anything is stored — see\nwriteWebhookErr.",
        "type": "array",
        "items": {
          "$ref": "#/definitions/github_com_webbuilder_server_internal_webhooks.EventType"
        }
      },
      "status": {
        "description": "Status lets a caller register (or PUT back to) an endpoint already\npaused (`disabled`). Empty defaults to `active`. `active`/`disabled`\nare always accepted. `failing` is a server-owned label\n(webhooks.MarkEndpointResult sets it) and is refused on write — UNLESS\nit exactly matches the value already stored: PUT is a full replace\n(see webhookItem), so echoing a `failing` endpoint's OWN status back\nunchanged while editing something else about it (its url, say) is a\nno-op on this field, not an attempt to set the label from outside, and\nis accepted (NEW-2). Any OTHER unrecognised value (`\"paused\"`, a typo)\nis refused regardless of what is currently stored.",
        "type": "string"
      },
      "url": {
        "type": "string"
      }
    }
  },
